export function creditRewards(ledger,j,now=Date.now()){if(!j)return ledger;const elapsed=Math.max(0,(j.pausedAt??now)-j.startedAt-j.pausedMs),{maxMs,creditedMs}=movementTimes(j.route,elapsed);if(maxMs<1)return ledger;const id=`${j.fromId}:${j.toId}:${j.startedAt}`,old=ledger.entries[id];if(old&&old.maxMs!==maxMs)throw Error('Conflicting journey reward');const measured=routeMileage(j.route,maxMs?Math.max(creditedMs,old?.creditedMs||0)/maxMs:0);if(old?.routeMetres!==undefined&&Math.abs(old.routeMetres-j.route.distanceMetres)>.1)throw Error('Conflicting mileage');if(old&&old.creditedMs>=creditedMs&&old.distanceByMode)return ledger;return{version:1,entries:{...ledger.entries,[id]:{fromId:j.fromId,toId:j.toId,startedAt:j.startedAt,maxMs,creditedMs:Math.max(creditedMs,old?.creditedMs||0),routeMetres:j.route.distanceMetres,distanceByMode:measured}}}}
